// stlport
// A run given as a pair of ends passed on as a start and a length, built
// without optimisation. The search helper uses the retail STLport shape.

#define _STLP_USE_OWN_NAMESPACE 1
#include "Common/STLTypedefs.h"
#include <algorithm>
#include <string>

extern "C" void _ReadWriteBarrier(void);
#pragma intrinsic(_ReadWriteBarrier)


struct BfmeRangePE
{
	char *m_bfmeAt;				// 0x0
	char *m_bfmeEnd;			// 0x4
};

class BfmeThingPE
{
public:
	void bfmeGoPE(const BfmeRangePE *span, void *what);

	unsigned int bfmeDoPE(char *at, void *what, int many);

	const char *m_bfmeAt;
	const char *m_bfmeEnd;
};

void BfmeThingPE::bfmeGoPE(const BfmeRangePE *span, void *what)
{
	bfmeDoPE(span->m_bfmeAt, what, span->m_bfmeEnd - span->m_bfmeAt);
}

#pragma optimize("gty", on)
unsigned int BfmeThingPE::bfmeDoPE(char *at, void *what, int many)
{
	const unsigned int npos = (unsigned int)-1;
	const char *first = m_bfmeAt;
	const char *last = m_bfmeEnd;

	if ((unsigned int)what + (unsigned int)many > (unsigned int)(last - first))
	{
		__asm { }
		return npos;
	}

	const char *result = std::search(
			first + (unsigned int)what, last, at, at + many,
			_STL::_Eq_traits<_STL::char_traits<char> >());
	if (result == last)
	{
		__asm { }
		return npos;
	}
	return result - first;
}

#pragma optimize("", off)
